customCSS:
.t, .history { color: #5b5e5a; }
.join { color: #8fb573; }
.part, .quit { color: #5b5e5a; }
.kick, .error { color: #e75a7c; }
.notice { color: #dbb671; }
.action { color: #aaaaff; }
.mode, .nick, .topic, .server { color: #70c2be; }
.highlight { color: #f1e9d2; background-color: #5b5e5a; border-left: 3px solid #aaaaff; padding-left: 8px; }
.reply { color: #5b5e5a; border-left: 2px solid #57a5e5; padding-left: 6px; }
.oper { color: #252623; background-color: #dbb671; }
.reactions { color: #57a5e5; background-color: #1c1e1b; }
.card { background-color: #1c1e1b; border-color: #5b5e5a; }
.card-title { color: #57a5e5; }
.card-desc { color: #5b5e5a; }
.daychange { color: #5b5e5a; border-color: #1c1e1b; }
